        n = len(arr)
        max_sum = 0

        # Function to calculate the maximum sum of increasing subsequence
        def max_sum_increasing_subseq(arr, start, end):
            if start >= end:
                return 0
            max_sum = 0
            for i in range(start + 1, end + 1):
                if arr[i] > arr[start]:
                    current_sum = arr[start] + arr[i] + max_sum_increasing_subseq(arr, i, end)
                    max_sum = max(max_sum, current_sum)
            return max_sum

        # Function to calculate the maximum sum of decreasing subsequence
        def max_sum_decreasing_subseq(arr, start, end):
            if start >= end:
                return 0
            max_sum = 0
            for i in range(start, end):
                if arr[i] > arr[i + 1]:
                    current_sum = arr[i] + arr[i + 1] + max_sum_decreasing_subseq(arr, i + 1, end)
                    max_sum = max(max_sum, current_sum)
